// Shader variables
let theShader;
let shaderBg;
//CECI ET UNE FONCTION
function preload() {
  // Charge le shader
  theShader = loadShader("https://openprocessing.org/sketch/2548578/files/vertex.glsl", "fragment.glsl");
}

function setup() {
  // Crée un canevas avec la taille de la fenêtre en mode WEBGL
  createCanvas(windowWidth, windowHeight, WEBGL);

  // Désactive le redimensionnement pour les écrans retina
  pixelDensity(1);
  noStroke();

  // Crée un buffer graphique pour le shader
  shaderBg = createGraphics(windowWidth, windowHeight, WEBGL);
}

function draw() {
  // Applique le shader
  shaderBg.shader(theShader);

  // Récupère les coordonnées de la souris et les mappe dans l'espace [-1, 1]
  let yMouse = (map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / height) * 2 - 1;
  let xMouse = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width) * 2 - 1;

  // Assure que les pixels sont carrés
  xMouse = (xMouse * width) / height;

  // Passe les informations interactives au shader
  theShader.setUniform("iResolution", [width, height]);
  theShader.setUniform("iTime", millis() / 3000.0);
  theShader.setUniform("iMouse", [xMouse, yMouse]);

  // Dessine le shader
  shaderBg.rect(-width / 2, -height / 2, width, height);
  image(shaderBg, -width / 2, -height / 2, width, height);
	drawSmiley(100, 100);
}
//CECI ET UNE FONCTION
function windowResized() {
  // Redimensionne le canevas et le buffer graphique pour le shader
  resizeCanvas(windowWidth, windowHeight);
  shaderBg = createGraphics(windowWidth, windowHeight, WEBGL);
  theShader.setUniform("iResolution", [width, height]);
}

// Fonction pour dessiner un smiley
function drawSmiley(x, y) {
  push();
  translate(x - width / 2, y - height / 2); // Ajuste la position pour WEBGL

  fill(255, 204, 0);
  ellipse(0, 0, 100, 100); // Tête

  fill(0); 
  ellipse(-20, -20, 15, 15); // Oeil gauche
  ellipse(20, -20, 15, 15); // Oeil droit

  //noFill();
  stroke(0);
  strokeWeight(3);
  arc(0, 10, 50, 30, 0, PI); // Bouche souriante

  pop();
}


