// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// Vertex attributes
attribute vec3 aPosition;
attribute vec2 aTexCoord;

// Pass-through to the fragment shader
varying vec2 vTexCoord;

void main() {
    // Pass texture coordinates to the fragment shader
    vTexCoord = aTexCoord;

    // Transform the position into normalized device coordinates (NDC)
    vec4 positionVec4 = vec4(aPosition, 1.0);

    // Scale and shift to NDC (Normalize Device Coordinate) range [-1, 1]
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

    // Set the final position of the vertex
    gl_Position = positionVec4;
}


// === Tab: fragment.glsl ===
/*
 * You can use this as a template to make shaders! Have fun!
 * Author: Juan Carlos Ponce Campuzano
 * https://www.patreon.com/jcponce
 * 13/Dc/2024
 * Inspired by ronwnor 
 * https://x.com/Pixelated_Donut
 */

#ifdef GL_ES
precision highp float;
#endif

uniform vec2 iResolution;
uniform float iTime;

varying vec2 vTexCoord;

#define PI 3.14159265359

float funPattern(float x, float y, float t) {
    float a = atan(y, x);
    float b = asin(sin(a - t + 3.0 * log(x*x + y*y)));
    float k = pow(2.0 * PI, 1.0 - sqrt(sin(6.0*a)*sin(6.0*a) + b*b));
    return 2.0 * b * cos(k) - sin(k) / (1.0/sin(12.0 * a));
}

vec3 pastelColor(float t) {
    return vec3(
        0.9 + 0.4 * cos(2.0 * PI * t + 0.0),
        0.5 + 0.5 * cos(2.0 * PI * t + 5.0),
        0.5 + 0.5 * cos(2.0 * PI * t + 4.0)
    ) * 0.8 + 0.2;
}

void main() {
    vec2 uv = vTexCoord * 3.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float patternValue = funPattern(uv.x, uv.y, iTime);

    vec3 color;
    if (patternValue < 0.0) {
        float hue = mix(0.2, 0.8, (patternValue - iTime) / 1.0);
        color = pastelColor(hue);
    } else {
        color = vec3(0.85, 0.85, 0.85); // Light rgb(226,154,154) for contrast
    }

    gl_FragColor = vec4(color, 1.0);
}

